<template>
  <view class="page">
    <animated-loading v-if="loading" text="正在布置餐厅场景..."></animated-loading>
    <template v-else-if="!result">
      <view class="hero"><view><text class="kicker">🍽️ 场景任务 · {{ stepIndex + 1 }}/{{ steps.length }}</text><text class="title">{{ mission.title }}</text></view><text class="time">约 {{ mission.estimatedMinutes }} 分钟</text><view class="bar"><view :style="{width:progress+'%'}"></view></view></view>
      <view v-if="step.type==='story'" class="story card"><view class="speaker">👩 Mia</view><text class="bubble">我们只有十分钟。请帮我点一份不辣的鸡肉套餐，我想喝橙汁；你可以点一份意面和水。</text><view class="goal"><text>本次任务</text><text>{{ mission.objective }}</text></view><button class="primary" @click="passStep">记住了，查看菜单</button></view>
      <view v-else-if="step.type==='menu'" class="card"><text class="stage">获取线索</text><text class="question">哪一项最符合 Mia 的要求？</text><view class="menu"><view v-for="item in menu" :key="item.name" class="menu-item" :class="{selected:selected===item.name}" @click="selected=item.name"><view><text class="food">{{item.icon}} {{item.name}}</text><text class="desc">{{item.desc}}</text></view><text class="price">{{item.price}}</text></view></view><button class="primary" :disabled="!selected" @click="checkMenu">确认选择</button></view>
      <view v-else-if="step.type==='dialogue'" class="card"><text class="stage">情境接话</text><view class="waiter">🧑‍🍳 Waiter</view><view class="dialogue-bubble"><text class="bubble-text">Good evening. Are you ready to order?</text><view class="dialogue-play" role="button" aria-label="播放这句英文" @click="playDialogue(DIALOGUE_TEXT)">🔊</view></view><text class="question">选择最自然的回应</text><view v-for="option in dialogueOptions" :key="option.text" class="choice" :class="choiceClass(option.text)" @click="chooseDialogue(option)">{{option.text}}</view><button v-if="answered" class="primary" @click="advance">继续</button></view>
      <view v-else-if="step.type==='build'" class="card"><text class="stage">组织表达</text><text class="question">把词块组成“我想要不辣的鸡肉套餐”</text><view class="sentence"><text v-if="!built.length">点击下方词块</text><view v-for="(word,i) in built" :key="i" class="chip active" @click="removeWord(i)">{{word}}</view></view><view class="chips"><view v-for="word in available" :key="word" class="chip" @click="addWord(word)">{{word}}</view></view><button class="primary" :disabled="!built.length" @click="checkBuild">提交句子</button></view>
      <view v-else-if="step.type==='speech'" class="card speech"><text class="stage">开口行动</text><view class="waiter">🧑‍🍳 Waiter</view><view class="dialogue-bubble"><text class="bubble-text">And what would you like to drink?</text><view class="dialogue-play" role="button" aria-label="播放这句英文" @click="playDialogue(DRINK_TEXT)">🔊</view></view><text class="target">A glass of water, please.</text><view class="listen" @click="playTarget">🔊 听标准表达</view><view class="mic" :class="{recording}" @click="toggleRecord">{{recording?'■':'🎙️'}}</view><text class="mic-tip">{{recording?'正在录音，点击停止':'点击录音并完整读出句子'}}</text><view v-if="speechScore" class="speech-result">发音得分 {{speechScore}} · {{speechFeedback}}</view><button v-if="speechScore>=60" class="primary" @click="advance">完成点餐</button><button v-else-if="speechFailed" class="secondary" @click="confirmPractice">评测不可用，我已完成跟读</button></view>
      <view v-else class="card boss"><text class="stage">场景挑战</text><text class="question">服务员说鸡肉套餐售罄，你应该怎么处理？</text><view class="dialogue-bubble"><text class="bubble-text">Sorry, the chicken meal is sold out.</text><view class="dialogue-play" role="button" aria-label="播放这句英文" @click="playDialogue(BOSS_TEXT)">🔊</view></view><view v-for="option in bossOptions" :key="option.text" class="choice" :class="choiceClass(option.text)" @click="chooseBoss(option)">{{option.text}}</view><view v-if="answered" class="coach">{{lastCorrect?'✅ 很自然，你成功换了一份餐。':'💡 sold out 表示售罄，可以礼貌地换一个选择。'}}</view><button v-if="answered" class="primary" @click="finish">完成任务</button></view>
    </template>
    <view v-else class="result card"><text class="result-icon">{{result.passed?'🏅':'🧭'}}</text><text class="result-title">{{result.passed?'点餐成功！':'任务还差一点'}}</text><text class="score">{{result.score}} 分</text><text class="ability">{{result.passed?'你现在可以看懂基础菜单、礼貌点餐并处理售罄情况。':'再练一次关键表达，就能独立完成点餐。'}}</text><view class="mastery"><text>本次能力</text><text>菜单信息提取 · 情境回应 · 句子组织 · 开口表达</text></view><text v-if="result.reward" class="reward">解锁「{{result.reward.badge}}」 · +{{result.reward.xp}} XP</text><button class="primary" @click="restart">{{result.passed?'再玩一次':'重新挑战'}}</button><button class="secondary" @click="back">返回场景</button></view>
  </view>
</template>

<script>
import { request, evaluateSpeech } from '@/utils/api.js';
import { playTts, clearTtsQueue } from '@/utils/tts-player.js';
import { getAudioSettings } from '@/utils/learning-settings.js';
import { isSameEnglishAnswer } from '@/utils/answer-normalization.js';
const TARGET='A glass of water, please.';
const DIALOGUE_TEXT='Good evening. Are you ready to order?';
const DRINK_TEXT='And what would you like to drink?';
const BOSS_TEXT='Sorry, the chicken meal is sold out.';
export default{data(){return{loading:true,mission:{},stepIndex:0,steps:[{id:'intro',type:'story'},{id:'menu',type:'menu'},{id:'dialogue',type:'dialogue'},{id:'build',type:'build'},{id:'speech',type:'speech'},{id:'boss',type:'boss'}],outcomes:[],selected:'',answered:false,lastCorrect:false,built:[],available:["I'd like",'the chicken meal,','not spicy,','please.'],recordManager:null,recording:false,speechScore:0,speechFeedback:'',speechFailed:false,result:null,autoPlay:true,audioTimer:null,DIALOGUE_TEXT,DRINK_TEXT,BOSS_TEXT,menu:[{icon:'🍗',name:'Chicken meal',desc:'Grilled chicken · mild or spicy',price:'¥38'},{icon:'🌶️',name:'Hot wings',desc:'Very spicy · six pieces',price:'¥32'},{icon:'🥗',name:'Green salad',desc:'Vegetables · no meat',price:'¥26'}],dialogueOptions:[{text:"Yes. We'd like to order, please.",correct:true},{text:'No, I am order.',correct:false},{text:'I ready yesterday.',correct:false}],bossOptions:[{text:'Then I’ll have the pasta, please.',correct:true},{text:'The chicken was yesterday.',correct:false},{text:'Give sold out to me.',correct:false}]}} ,computed:{step(){return this.steps[this.stepIndex]},progress(){return Math.round(this.stepIndex*100/this.steps.length)}},async onLoad(){try{const [data,audioSettings]=await Promise.all([request('/adventure-course/mission/restaurant'),getAudioSettings()]);this.mission=data.mission||{};this.autoPlay=audioSettings.autoPlay}catch(e){uni.showToast({title:e.message||'加载失败',icon:'none'})}finally{this.loading=false}this.initRecorder();this.scheduleDialogueAudio()},onUnload(){if(this.audioTimer)clearTimeout(this.audioTimer);clearTtsQueue();if(this.recording)this.recordManager?.stop()},methods:{record(id,passed){const old=this.outcomes.find(x=>x.id===id);if(old)old.passed=passed;else this.outcomes.push({id,passed})},passStep(){this.advance()},advance(){this.answered=false;this.selected='';this.stepIndex=Math.min(this.steps.length-1,this.stepIndex+1);this.scheduleDialogueAudio()},checkMenu(){const ok=this.selected==='Chicken meal';this.record('menu',ok);if(!ok)return uni.showModal({title:'再看看菜单',content:'Mia 要的是鸡肉、不辣。注意菜品描述中的 spicy。',showCancel:false});this.advance()},choiceClass(text){if(!this.answered)return'';const list=this.step.type==='boss'?this.bossOptions:this.dialogueOptions,item=list.find(x=>x.text===text);if(item?.correct)return'correct';return text===this.selected?'wrong':'dim'},chooseDialogue(option){if(this.answered)return;this.selected=option.text;this.answered=true;this.lastCorrect=option.correct;this.record('dialogue',option.correct)},addWord(word){this.built.push(word);this.available=this.available.filter(x=>x!==word)},removeWord(i){this.available.push(this.built[i]);this.built.splice(i,1)},checkBuild(){const ok=isSameEnglishAnswer(this.built.join(' '),"I'd like the chicken meal, not spicy, please.");this.record('build',ok);if(!ok)return uni.showModal({title:'顺序需要调整',content:"常用结构是：I'd like + 餐品 + 补充要求 + please.",showCancel:false});this.advance()},dialogueText(){return this.step?.type==='dialogue'?DIALOGUE_TEXT:(this.step?.type==='speech'?DRINK_TEXT:(this.step?.type==='boss'?BOSS_TEXT:''))},scheduleDialogueAudio(){if(this.audioTimer)clearTimeout(this.audioTimer);if(!this.autoPlay)return;this.audioTimer=setTimeout(()=>{this.audioTimer=null;const text=this.dialogueText();if(text)this.playDialogue(text)},350)},playDialogue(text){playTts(text,3).catch(()=>uni.showToast({title:'播放失败，请重试',icon:'none'}))},playTarget(){playTts(TARGET,3).catch(()=>uni.showToast({title:'播放失败',icon:'none'}))},initRecorder(){try{this.recordManager=uni.getRecorderManager();this.recordManager.onStop(res=>{this.recording=false;if(res.tempFilePath)this.evaluate(res.tempFilePath)});this.recordManager.onError(()=>{this.recording=false;this.speechFailed=true})}catch(e){this.speechFailed=true}},toggleRecord(){if(this.recording){this.recordManager.stop();return}this.speechFailed=false;this.recording=true;this.recordManager.start({duration:15000,format:'mp3',sampleRate:16000,numberOfChannels:1})},evaluate(path){uni.getFileSystemManager().readFile({filePath:path,encoding:'base64',success:async file=>{try{const data=await evaluateSpeech(file.data,TARGET,'read_sentence','mp3');this.speechScore=Number(data.score||0);this.speechFeedback=data.feedback||'';if(this.speechScore>=60)this.record('speech',true)}catch(e){this.speechFailed=true;uni.showToast({title:e.message||'评测暂不可用',icon:'none'})}},fail:()=>{this.speechFailed=true}})},confirmPractice(){this.record('speech',true);this.speechScore=60;this.speechFeedback='已完成跟读练习'},chooseBoss(option){if(this.answered)return;this.selected=option.text;this.answered=true;this.lastCorrect=option.correct;this.record('boss',option.correct)},async finish(){try{this.result=await request('/adventure-course/mission/restaurant/complete','POST',{steps:this.outcomes})}catch(e){uni.showToast({title:e.message||'保存失败',icon:'none'})}},restart(){if(this.audioTimer)clearTimeout(this.audioTimer);clearTtsQueue();this.stepIndex=0;this.outcomes=[];this.selected='';this.answered=false;this.built=[];this.available=["I'd like",'the chicken meal,','not spicy,','please.'];this.speechScore=0;this.speechFailed=false;this.result=null},back(){uni.navigateBack()}}}
</script>

<style>
.page{box-sizing:border-box;min-height:100vh;padding:24rpx;background:linear-gradient(180deg,#fff5d9,#f5f3ea 45%,#e8f2ef)}.hero{position:relative;padding:28rpx;border-radius:28rpx;background:linear-gradient(135deg,#233f57,#176f72);color:#fff;box-shadow:0 16rpx 36rpx rgba(25,68,77,.2)}.kicker,.title{display:block}.kicker{font-size:21rpx;color:#9ce2d5;font-weight:800}.title{margin-top:8rpx;font-size:38rpx;font-weight:900}.time{position:absolute;right:26rpx;top:29rpx;font-size:20rpx;color:#d4ebe7}.bar{height:9rpx;margin-top:24rpx;border-radius:8rpx;background:rgba(255,255,255,.18);overflow:hidden}.bar view{height:100%;background:#ffd76a;transition:width .3s}.card{margin-top:24rpx;padding:30rpx 26rpx;border-radius:28rpx;background:#fff;box-shadow:0 10rpx 30rpx rgba(40,59,70,.09)}.speaker,.waiter,.stage{font-size:22rpx;font-weight:900;color:#14877e}.bubble{display:block;margin-top:16rpx;padding:22rpx;border-radius:8rpx 22rpx 22rpx;background:#e9f7f4;font-size:28rpx;line-height:1.6;color:#294256}.bubble.left{border-radius:8rpx 22rpx 22rpx}.dialogue-bubble{display:flex;align-items:center;margin-top:16rpx;padding:20rpx 18rpx;border-radius:8rpx 22rpx 22rpx;background:#e9f7f4}.bubble-text{flex:1;color:#294256;font-size:28rpx;line-height:1.55}.dialogue-play{display:flex;flex-shrink:0;align-items:center;justify-content:center;width:58rpx;height:58rpx;margin-left:14rpx;border-radius:50%;background:#fff;color:#11877c;font-size:25rpx;box-shadow:0 3rpx 10rpx rgba(17,135,124,.12)}.goal{margin-top:26rpx;padding:22rpx;border:2rpx dashed #efbd4c;border-radius:18rpx;background:#fff9e8}.goal text{display:block;font-size:23rpx;line-height:1.55;color:#72551b}.goal text:first-child{font-weight:900;color:#b5780d}.question{display:block;margin:20rpx 0;font-size:31rpx;font-weight:900;line-height:1.5;color:#273e52}.menu-item{display:flex;align-items:center;justify-content:space-between;margin-top:14rpx;padding:20rpx;border:2rpx solid #e4e8e6;border-radius:18rpx}.menu-item.selected{border-color:#169487;background:#ecfaf6}.food,.desc{display:block}.food{font-size:26rpx;font-weight:900;color:#30495b}.desc{margin-top:6rpx;font-size:20rpx;color:#849099}.price{font-size:24rpx;font-weight:900;color:#b77516}.choice{margin-top:14rpx;padding:22rpx;border:2rpx solid #e3e8e9;border-radius:17rpx;font-size:25rpx;line-height:1.4;color:#344b5d}.choice.correct{border-color:#38ae7b;background:#edfaf4;color:#167957}.choice.wrong{border-color:#df6860;background:#fff1ef;color:#ba4842}.choice.dim{opacity:.5}.sentence{display:flex;flex-wrap:wrap;gap:12rpx;min-height:100rpx;padding:18rpx;border:2rpx dashed #b9c9cc;border-radius:18rpx;color:#98a3a8}.chips{display:flex;flex-wrap:wrap;gap:12rpx;margin-top:22rpx}.chip{padding:14rpx 18rpx;border-radius:12rpx;background:#edf2f4;color:#365267;font-size:24rpx}.chip.active{background:#dff4ef;color:#117d70}.target{display:block;margin-top:24rpx;font-size:33rpx;font-weight:900;text-align:center;color:#273f55}.listen{text-align:center;margin-top:18rpx;color:#14877e}.speech{text-align:center}.speech .stage,.speech .waiter,.speech .bubble{text-align:left}.mic{width:120rpx;height:120rpx;line-height:120rpx;margin:34rpx auto 12rpx;border-radius:50%;background:linear-gradient(135deg,#ef775e,#dc4e55);color:#fff;font-size:45rpx;box-shadow:0 10rpx 24rpx rgba(213,68,73,.28)}.mic.recording{animation:pulse 1s infinite}.mic-tip,.speech-result{display:block;font-size:21rpx;color:#7d8993}.speech-result{margin-top:18rpx;color:#158273;font-weight:800}.coach,.mastery{margin-top:22rpx;padding:18rpx;border-radius:15rpx;background:#eef7f5;color:#32645e;font-size:22rpx;line-height:1.5}.primary,.secondary{height:84rpx;line-height:84rpx;margin-top:26rpx;border:0;border-radius:18rpx;background:#1d6f72;color:#fff;font-size:28rpx;font-weight:900}.primary[disabled]{opacity:.4}.primary:after,.secondary:after{border:0}.secondary{margin-top:14rpx;background:#edf1f2;color:#516575}.result{text-align:center}.result-icon{font-size:80rpx}.result-title,.score,.ability,.reward{display:block}.result-title{margin-top:15rpx;font-size:39rpx;font-weight:900;color:#263f54}.score{margin-top:12rpx;font-size:62rpx;font-weight:900;color:#168d82}.ability{margin-top:18rpx;font-size:24rpx;line-height:1.7;color:#647780}.mastery text{display:block}.mastery text:first-child{font-weight:900}.reward{margin-top:22rpx;color:#b47710;font-weight:900}@keyframes pulse{50%{transform:scale(1.08);box-shadow:0 0 0 18rpx rgba(220,78,85,.12)}}
</style>
